text:
I'll create a comprehensive fitness tracker app as a single HTML file for you. Here it is:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>FitPulse - Fitness Tracker</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --primary: #6C5CE7;
            --primary-light: #a29bfe;
            --secondary: #00cec9;
            --accent: #fd79a8;
            --danger: #e17055;
            --success: #00b894;
            --dark: #2d3436;
            --dark-light: #636e72;
            --bg: #0a0a1a;
            --bg-card: #141428;
            --bg-card-hover: #1a1a35;
            --text: #f0f0f5;
            --text-muted: #9a9ab0;
            --border: #2a2a45;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: var(--bg);
            color: var(--text);
            min-height: 100vh;
            overflow-x: hidden;
        }

        /* Background animation */
        body::before {
            content: '';
            position: fixed;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(ellipse at 20% 50%, rgba(108, 92, 231, 0.08) 0%, transparent 50%),
                        radial-gradient(ellipse at 80% 20%, rgba(0, 206, 201, 0.06) 0%, transparent 50%),
                        radial-gradient(ellipse at 50% 80%, rgba(253, 121, 168, 0.05) 0%, transparent 50%);
            z-index: -1;
            animation: bgShift 20s ease-in-out infinite alternate;
        }

        @keyframes bgShift {
            0% { transform: translate(0, 0); }
            100% { transform: translate(-5%, -5%); }
        }

        /* Header */
        .header {
            background: rgba(20, 20, 40, 0.8);
            backdrop-filter: blur(20px);
            border-bottom: 1px solid var(--border);
            padding: 16px 24px;
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .header-content {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 10px;
            font-size: 24px;
            font-weight: 800;
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .logo-icon {
            width: 36px;
            height: 36px;
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
            -webkit-text-fill-color: white;
        }

        .header-date {
            color: var(--text-muted);
            font-size: 14px;
        }

        /* Navigation */
        .nav {
            display: flex;
            gap: 4px;
            max-width: 1200px;
            margin: 16px auto;
            padding: 0 24px;
            background: var(--bg-card);
            border-radius: 16px;
            overflow-x: auto;
            border: 1px solid var(--border);
        }

        .nav-btn {
            flex: 1;
            padding: 14px 20px;
            background: none;
            border: none;
            color: var(--text-muted);
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            border-radius: 12px;
            transition: all 0.3s;
            white-space: nowrap;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .nav-btn:hover {
            color: var(--text);
            background: rgba(108, 92, 231, 0.1);
        }

        .nav-btn.active {
            background: linear-gradient(135deg, var(--primary), #5a4bd1);
            color: white;
            box-shadow: 0 4px 15px rgba(108, 92, 231, 0.3);
        }

        /* Main Content */
        .main {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 24px 100px;
        }

        .page {
            display: none;
            animation: fadeIn 0.4s ease;
        }

        .page.active {
            display: block;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Dashboard */
        .stats-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
            gap: 16px;
            margin-bottom: 24px;
        }

        .stat-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 20px;
            padding: 24px;
            transition: all 0.3s;
            position: relative;
            overflow: hidden;
        }

        .stat-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            border-radius: 20px 20px 0 0;
        }

        .stat-card:nth-child(1)::before { background: linear-gradient(90deg, var(--primary), var(--primary-light)); }
        .stat-card:nth-child(2)::before { background: linear-gradient(90deg, var(--secondary), #55efc4); }
        .stat-card:nth-child(3)::before { background: linear-gradient(90deg, var(--accent), #fab1a0); }
        .stat-card:nth-child(4)::before { background: linear-gradient(90deg, var(--danger), #fdcb6e); }

        .stat-card:hover {
            transform: translateY(-2px);
            border-color: rgba(108, 92, 231, 0.3);
        }

        .stat-label {
            font-size: 13px;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 8px;
        }

        .stat-value {
            font-size: 36px;
            font-weight: 800;
            margin-bottom: 4px;
        }

        .stat-card:nth-child(1) .stat-value { color: var(--primary-light); }
        .stat-card:nth-child(2) .stat-value { color: var(--secondary); }
        .stat-card:nth-child(3) .stat-value { color: var(--accent); }
        .stat-card:nth-child(4) .stat-value { color: var(--danger); }

        .stat-sub {
            font-size: 13px;
            color: var(--text-muted);
        }

        .stat-icon {
            position: absolute;
            top: 20px;
            right: 20px;
            font-size: 28px;
            opacity: 0.6;
        }

        /* Charts Section */
        .chart-section {
            display: grid;
            grid-template-columns: 2fr 1fr;
            gap: 16px;
            margin-bottom: 24px;
        }

        @media (max-width: 768px) {
            .chart-section {
                grid-template-columns: 1fr;
            }
        }

        .card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 20px;
            padding: 24px;
        }

        .card-title {
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 20px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        /* Weekly Chart */
        .bar-chart {
            display: flex;
            align-items: flex-end;
            gap: 12px;
            height: 200px;
            padding-top: 20px;
        }

        .bar-wrapper {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 8px;
            height: 100%;
            justify-content: flex-end;
        }

        .bar {
            width: 100%;
            max-width: 40px;
            border-radius: 8px 8px 4px 4px;
            background: linear-gradient(180deg, var(--primary), var(--primary-light));
            transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
            min-height: 4px;
            position: relative;
            cursor: pointer;
        }

        .bar:hover {
            filter: brightness(1.2);
            transform: scaleX(1.1);
        }

        .bar-label {
            font-size: 12px;
            color: var(--text-muted);
            font-weight: 600;
        }

        .bar-value {
            font-size: 11px;
            color: var(--text);
            font-weight: 700;
        }

        /* Goals */
        .goal-item {
            margin-bottom: 20px;
        }

        .goal-header {
            display: flex;
            justify-content: space-between;
            margin-bottom: 8px;
            font-size: 14px;
        }

        .goal-name {
            font-weight: 600;
        }

        .goal-progress {
            color: var(--text-muted);
        }

        .progress-bar {
            height: 10px;
            background: rgba(108, 92, 231, 0.15);
            border-radius: 10px;
            overflow: hidden;
        }

        .progress-fill {
            height: 100%;
            border-radius: 10px;
            transition: width 1s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .progress-fill.purple { background: linear-gradient(90deg, var(--primary), var(--primary-light)); }
        .progress-fill.teal { background: linear-gradient(90deg, var(--secondary), #55efc4); }
        .progress-fill.pink { background: linear-gradient(90deg, var(--accent), #fab1a0); }
        .progress-fill.orange { background: linear-gradient(90deg, var(--danger), #fdcb6e); }

        /* Workout Logger */
        .workout-form {
            display: grid;
            gap: 16px;
            margin-bottom: 24px;
        }

        .form-row {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 16px;
        }

        .form-group {
            display: flex;
            flex-direction: column;
            gap: 6px;
        }

        .form-group label {
            font-size: 13px;
            font-weight: 600;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .form-group input,
        .form-group select,
        .form-group textarea {
            background: rgba(42, 42, 69, 0.5);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 12px 16px;
            color: var(--text);
            font-size: 15px;
            font-family: inherit;
            transition: all 0.3s;
        }

        .form-group input:focus,
        .form-group select:focus,
        .form-group textarea:focus {
            outline: none;
            border-color: var(--primary);
            box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.15);
        }

        .form-group select {
            cursor: pointer;
        }

        .btn {
            padding: 14px 28px;
            border: none;
            border-radius: 12px;
            font-size: 15px;
            font-weight: 700;
            cursor: pointer;
            transition: all 0.3s;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--primary), #5a4bd1);
            color: white;
            box-shadow: 0 4px 15px rgba(108, 92, 231, 0.3);
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(108, 92, 231, 0.4);
        }

        .btn-secondary {
            background: rgba(108, 92, 231, 0.15);
            color: var(--primary-light);
            border: 1px solid rgba(108, 92, 231, 0.3);
        }

        .btn-secondary:hover {
            background: rgba(108, 92, 231, 0.25);
        }

        .btn-danger {
            background: rgba(225, 112, 85, 0.15);
            color: var(--danger);
            border: 1px solid rgba(225, 112, 85, 0.3);
            padding: 8px 16px;
            font-size: 13px;
        }

        .btn-danger:hover {
            background: rgba(225, 112, 85, 0.25);
        }

        /* Exercise List in Form */
        .exercise-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .exercise-entry {
            background: rgba(42, 42, 69, 0.3);
            border: 1px solid var(--border);
            border-radius: 16px;
            padding: 16px;
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr auto;
            gap: 12px;
            align-items: end;
            animation: slideIn 0.3s ease;
        }

        @keyframes slideIn {
            from { opacity: 0; transform: translateX(-20px); }
            to { opacity: 1; transform: translateX(0); }
        }

        @media (max-width: 768px) {
            .exercise-entry {
                grid-template-columns: 1fr 1fr;
            }
        }

        .remove-exercise {
            background: rgba(225, 112, 85, 0.1);
            border: none;
            color: var(--danger);
            width: 36px;
            height: 36px;
            border-radius: 10px;
            cursor: pointer;
            font-size: 18px;
            transition: all 0.3s;
        }

        .remove-exercise:hover {
            background: rgba(225, 112, 85, 0.2);
        }

        /* Workout History */
        .workout-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 20px;
            padding: 24px;
            margin-bottom: 16px;
            transition: all 0.3s;
        }

        .workout-card:hover {
            border-color: rgba(108, 92, 231, 0.3);
        }

        .workout-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 16px;
        }

        .workout-type {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .workout-type-icon {
            width: 44px;
            height: 44px;
            border-radius: 14px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 22px;
        }

        .type-strength .workout-type-icon { background: rgba(108, 92, 231, 0.15); }
        .type-cardio .workout-type-icon { background: rgba(253, 121, 168, 0.15); }
        .type-flexibility .workout-type-icon { background: rgba(0, 206, 201, 0.15); }
        .type-sports .workout-type-icon { background: rgba(225, 112, 85, 0.15); }

        .workout-type-name {
            font-weight: 700;
            font-size: 17px;
        }

        .workout-type-date {
            font-size: 13px;
            color: var(--text-muted);
        }

        .workout-meta {
            display: flex;
            gap: 20px;
            text-align: right;
        }

        .workout-meta-item {
            font-size: 13px;
            color: var(--text-muted);
        }

        .workout-meta-value {
            font-size: 18px;
            font-weight: 700;
            color: var(--text);
        }

        .workout-exercises {
            display: grid;
            gap: 8px;
        }

        .exercise-row {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 10px 14px;
            background: rgba(42, 42, 69, 0.3);
            border-radius: 10px;
            font-size: 14px;
        }

        .exercise-name {
            font-weight: 600;
        }

        .exercise-details {
            color: var(--text-muted);
        }

        /* Timer Page */
        .timer-container {
            text-align: center;
            padding: 40px 0;
        }

        .timer-display {
            font-size: 80px;
            font-weight: 800;
            font-variant-numeric: tabular-nums;
            margin: 30px 0;
            background: linear-gradient(135deg, var(--primary-light), var(--secondary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        @media (max-width: 480px) {
            .timer-display { font-size: 52px; }
        }

        .timer-controls {
            display: flex;
            gap: 16px;
            justify-content: center;
            margin-bottom: 40px;
        }

        .timer-btn {
            width: 64px;
            height: 64px;
            border-radius: 50%;
            border: none;
            font-size: 24px;
            cursor: pointer;
            transition: all 0.3s;
        }

        .timer-btn.start {
            background: linear-gradient(135deg, var(--success), #55efc4);
            color: white;
            box-shadow: 0 4px 15px rgba(0, 184, 148, 0.3);
        }

        .timer-btn.pause {
            background: linear-gradient(135deg, #fdcb6e, #e17055);
            color: white;
            box-shadow: 0 4px 15px rgba(253, 203, 110, 0.3);
        }

        .timer-btn.stop {
            background: linear-gradient(135deg, var(--danger), #fab1a0);
            color: white;
            box-shadow: 0 4px 15px rgba(225, 112, 85, 0.3);
        }

        .timer-btn.lap {
            background: linear-gradient(135deg, var(--primary), var(--primary-light));
            color: white;
            box-shadow: 0 4px 15px rgba(108, 92, 231, 0.3);
        }

        .timer-btn:hover {
            transform: scale(1.1);
        }

        .timer-btn:active {
            transform: scale(0.95);
        }

        /* Timer Mode Tabs */
        .timer-modes {
            display: flex;
            gap: 8px;
            justify-content: center;
            margin-bottom: 20px;
        }

        .timer-mode-btn {
            padding: 10px 24px;
            border-radius: 12px;
            border: 1px solid var(--border);
            background: rgba(42, 42, 69, 0.3);
            color: var(--text-muted);
            font-weight: 600;
            font-size: 14px;
            cursor: pointer;
            transition: all 0.3s;
        }

        .timer-mode-btn.active {
            background: rgba(108, 92, 231, 0.2);
            color: var(--primary-light);
            border-color: var(--primary);
        }

        /* Countdown settings */
        .countdown-settings {
            display: flex;
            gap: 12px;
            justify-content: center;
            margin-bottom: 20px;
            align-items: center;
        }

        .countdown-settings input {
            width: 80px;
            text-align: center;
            background: rgba(42, 42, 69, 0.5);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 10px;
            color: var(--text);
            font-size: 18px;
            font-weight: 700;
        }

        .countdown-settings input:focus {
            outline: none;
            border-color: var(--primary);
        }

        .countdown-settings span {
            color: var(--text-muted);
            font-weight: 600;
        }

        /* Laps */
        .laps-list {
            max-width: 500px;
            margin: 0 auto;
        }

        .lap-item {
            display: flex;
            justify-content: space-between;
            padding: 12px 20px;
            border-bottom: 1px solid var(--border);
            font-size: 14px;
            animation: fadeIn 0.3s ease;
        }

        .lap-number {
            font-weight: 700;
            color: var(--primary-light);
        }

        .lap-time {
            font-variant-numeric: tabular-nums;
            color: var(--text-muted);
        }

        .lap-split {
            font-weight: 600;
        }

        /* Body Stats Page */
        .body-stats-form {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 16px;
            margin-bottom: 24px;
        }

        .body-stats-history {
            overflow-x: auto;
        }

        .stats-table {
            width: 100%;
            border-collapse: separate;
            border-spacing: 0;
        }

        .stats-table th {
            background: rgba(108, 92, 231, 0.1);
            padding: 14px 16px;
            text-align: left;
            font-size: 13px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--text-muted);
            border-bottom: 1px solid var(--border);
        }

        .stats-table th:first-child { border-radius: 12px 0 0 0; }
        .stats-table th:last-child { border-radius: 0 12px 0 0; }

        .stats-table td {
            padding: 14px 16px;
            border-bottom: 1px solid var(--border);
            font-size: 14px;
        }

        .stats-table tr:hover td {
            background: rgba(108, 92, 231, 0.05);
        }

        .trend-up { color: var(--danger); }
        .trend-down { color: var(--success); }
        .trend-same { color: var(--text-muted); }

        /* Recent Activity */
        .activity-list {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .activity-item {
            display: flex;
            align-items: center;
            gap: 16px;
            padding: 14px 18px;
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 14px;
            transition: all 0.3s;
        }

        .activity-item:hover {
            border-color: rgba(108, 92, 231, 0.3);
        }

        .activity-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            flex-shrink: 0;
        }

        .activity-text {
            flex: 1;
            font-size: 14px;
        }

        .activity-time {
            font-size: 12px;
            color: var(--text-muted);
            white-space: nowrap;
        }

        /* Empty State */
        .empty-state {
            text-align: center;
            padding: 60px 20px;
            color: var(--text-muted);
        }

        .empty-state-icon {
            font-size: 64px;
            margin-bottom: 16px;
            opacity: 0.5;
        }

        .empty-state-text {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 8px;
            color: var(--text);
        }

        /* Toast Notification */
        .toast {
            position: fixed;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%) translateY(100px);
            background: var(--bg-card);
            border: 1px solid var(--border);
            padding: 16px 28px;
            border-radius: 16px;
            font-weight: 600;
            z-index: 1000;
            transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .toast.show {
            transform: translateX(-50%) translateY(0);
        }

        .toast.success { border-color: var(--success); }
        .toast.error { border-color: var(--danger); }

        /* Circular Progress */
        .circular-progress {
            position: relative;
            width: 120px;
            height: 120px;
            margin: 0 auto;
        }

        .circular-progress svg {
            transform: rotate(-90deg);
        }

        .circular-progress .bg {
            fill: none;
            stroke: rgba(108, 92, 231, 0.1);
            stroke-width: 8;
        }

        .circular-progress .fg {
            fill: none;
            stroke: url(#gradient);
            stroke-width: 8;
            stroke-linecap: round;
            transition: stroke-dashoffset 1s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .circular-progress .center-text {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            text-align: center;
        }

        .circular-progress .center-value {
            font-size: 28px;
            font-weight: 800;
            color: var(--primary-light);
        }

        .circular-progress .center-label {
            font-size: 11px;
            color: var(--text-muted);
            text-transform: uppercase;
        }

        /* Streak display */
        .streak-display {
            text-align: center;
            padding: 20px;
        }

        .streak-flames {
            font-size: 48px;
            margin-bottom: 8px;
        }

        .streak-count {
            font-size: 36px;
            font-weight: 800;
            color: var(--danger);
        }

        .streak-label {
            font-size: 14px;
            color: var(--text-muted);
        }

        /* Delete All Button */
        .danger-zone {
            margin-top: 40px;
            padding: 24px;
            border: 1px dashed rgba(225, 112, 85, 0.3);
            border-radius: 16px;
            text-align: center;
        }

        /* Scrollbar */
        ::-webkit-scrollbar {
            width: 6px;
        }

        ::-webkit-scrollbar-track {
            background: transparent;
        }

        ::-webkit-scrollbar-thumb {
            background: var(--border);
            border-radius: 3px;
        }

        /* Responsive */
        @media (max-width: 600px) {
            .stats-grid {
                grid-template-columns: 1fr 1fr;
            }

            .stat-card {
                padding: 16px;
            }

            .stat-value {
                font-size: 28px;
            }

            .nav {
                margin: 12px 16px;
            }

            .nav-btn {
                padding: 12px 14px;
                font-size: 13px;
            }

            .main {
                padding: 0 16px 100px;
            }

            .workout-header {
                flex-direction: column;
                align-items: flex-start;
                gap: 12px;
            }

            .workout-meta {
                width: 100%;
                justify-content: flex-start;
            }
        }
    </style>
</head>
<body>
    <!-- SVG Gradient Definition -->
    <svg width="0" height="0">
        <defs>
            <linearGradient id="gradient" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stop-color="#6C5CE7" />
                <stop offset="100%" stop-color="#00cec9" />
            </linearGradient>
        </defs>
    </svg>

    <!-- Header -->
    <header class="header">
