    <!-- Main Content -->
    <main class="main">

        <!-- Dashboard Page -->
        <div class="page active" id="page-dashboard">
            <div class="stats-grid">
                <div class="stat-card">
                    <div class="stat-icon">🏋️</div>
                    <div class="stat-label">Total Workouts</div>
                    <div class="stat-value" id="totalWorkouts">0</div>
                    <div class="stat-sub">All time</div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon">🔥</div>
                    <div class="stat-label">Calories Burned</div>
                    <div class="stat-value" id="totalCalories">0</div>
                    <div class="stat-sub">This week</div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon">⏱️</div>
                    <div class="stat-label">Active Minutes</div>
                    <div class="stat-value" id="totalMinutes">0</div>
                    <div class="stat-sub">This week</div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon">📈</div>
                    <div class="stat-label">This Week</div>
                    <div class="stat-value" id="weekWorkouts">0</div>
                    <div class="stat-sub">workouts completed</div>
                </div>
            </div>

            <div class="chart-section">
                <div class="card">
                    <div class="card-title">📊 Weekly Activity</div>
                    <div class="bar-chart" id="weeklyChart"></div>
                </div>
                <div class="card">
                    <div class="card-title">🎯 Weekly Goals</div>
                    <div id="goalsContainer">
                        <div class="goal-item">
                            <div class="goal-header">
                                <span class="goal-name">Workouts</span>
                                <span class="goal-progress" id="goalWorkoutText">0/5</span>
                            </div>
                            <div class="progress-bar">
                                <div class="progress-fill purple" id="goalWorkoutBar" style="width: 0%"></div>
                            </div>
                        </div>
                        <div class="goal-item">
                            <div class="goal-header">
                                <span class="goal-name">Calories</span>
                                <span class="goal-progress" id="goalCalorieText">0/2000</span>
                            </div>
                            <div class="progress-bar">
                                <div class="progress-fill teal" id="goalCalorieBar" style="width: 0%"></div>
                            </div>
                        </div>
                        <div class="goal-item">
                            <div class="goal-header">
                                <span class="goal-name">Active Minutes</span>
                                <span class="goal-progress" id="goalMinuteText">0/150</span>
                            </div>
                            <div class="progress-bar">
                                <div class="progress-fill pink" id="goalMinuteBar" style="width: 0%"></div>
                            </div>
                        </div>
                    </div>

                    <div class="streak-display" style="margin-top: 20px; border-top: 1px solid var(--border); padding-top: 20px;">
                        <div class="streak-flames">🔥</div>
                        <div class="streak-count" id="streakCount">0</div>
                        <div class="streak-label">Day Streak</div>
                    </div>
                </div>
            </div>

            <div class="card">
                <div class="card-title">🕒 Recent Activity</div>
                <div class="activity-list" id="recentActivity">
                    <div class="empty-state">
                        <div class="empty-state-icon">🏃</div>
                        <div class="empty-state-text">No activities yet</div>
                        <p>Log your first workout to get started!</p>
                    </div>
                </div>
            </div>
        </div>

        <!-- Log Workout Page -->
        <div class="page" id="page-log">
            <div class="card" style="margin-bottom: 24px;">
                <div class="card-title">💪 Log New Workout</div>
                <form class="workout-form" id="workoutForm">
                    <div class="form-row">
                        <div class="form-group">
                            <label>Workout Type</label>
                            <select id="workoutType" required>
                                <option value="">Select type...</option>
                                <option value="strength">🏋️ Strength Training</option>
                                <option value="cardio">🏃 Cardio</option>
                                <option value="flexibility">🧘 Flexibility / Yoga</option>
                                <option value="sports">⚽ Sports</option>
                            </select>
                        </div>
                        <div class="form-group">
                            <label>Date</label>
                            <input type="date" id="workoutDate" required>
                        </div>
                        <div class="form-group">
                            <label>Duration (minutes)</label>
                            <input type="number" id="workoutDuration" placeholder="e.g., 45" min="1" required>
                        </div>
                        <div class="form-group">
                            <label>Calories Burned</label>
                            <input type="number" id="workoutCalories" placeholder="e.g., 300" min="0">
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Notes (optional)</label>
                        <textarea id="workoutNotes" rows="2" placeholder="How did it go?"></textarea>
                    </div>

                    <div class="card-title" style="margin-top: 10px;">🎯 Exercises</div>
                    <div class="exercise-list" id="exerciseList"></div>

                    <div style="display: flex; gap: 12px; flex-wrap: wrap;">
                        <button type="button" class="btn btn-secondary" onclick="addExercise()">+ Add Exercise</button>
                        <button type="submit" class="btn btn-primary" style="flex: 1; min-width: 200px;">✅ Save Workout</button>
                    </div>
                </form>
            </div>

            <!-- Quick Add Templates -->
            <div class="card">
                <div class="card-title">⚡ Quick Templates</div>
                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px;">
                    <button class="btn btn-secondary" onclick="loadTemplate('push')">🏋️ Push Day</button>
                    <button class="btn btn-secondary" onclick="loadTemplate('pull')">💪 Pull Day</button>
                    <button class="btn btn-secondary" onclick="loadTemplate('legs')">🦵 Leg Day</button>
                    <button class="btn btn-secondary" onclick="loadTemplate('cardio')">🏃 Cardio Session</button>
                    <button class="btn btn-secondary" onclick="loadTemplate('fullbody')">🔥 Full Body</button>
                    <button class="btn btn-secondary" onclick="loadTemplate('yoga')">🧘 Yoga Flow</button>
                </div>
            </div>
        </div>

        <!-- History Page -->
        <div class="page" id="page-history">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; flex-wrap: wrap; gap: 12px;">
                <h2>Workout History</h2>
                <div style="display: flex; gap: 8px;">
                    <select id="historyFilter" onchange="renderHistory()" style="background: var(--bg-card); border: 1px solid var(--border); border-radius: 10px; padding: 10px 14px; color: var(--text); font-size: 14px;">
                        <option value="all">All Types</option>
                        <option value="strength">🏋️ Strength</option>
                        <option value="cardio">🏃 Cardio</option>
                        <option value="flexibility">🧘 Flexibility</option>
                        <option value="sports">⚽ Sports</option>
                    </select>
                </div>
            </div>
            <div id="historyContainer"></div>
        </div>

        <!-- Timer Page -->
        <div class="page" id="page-timer">
            <div class="card">
                <div class="timer-container">
                    <div class="timer-modes">
                        <button class="timer-mode-btn active" data-mode="stopwatch" onclick="switchTimerMode('stopwatch')">Stopwatch</button>
                        <button class="timer-mode-btn" data-mode="countdown" onclick="switchTimerMode('countdown')">Countdown</button>
                    </div>

                    <div class="countdown-settings" id="countdownSettings" style="display: none;">
                        <input type="number" id="countdownMin" value="5" min="0" max="99" placeholder="Min">
                        <span>:</span>
                        <input type="number" id="countdownSec" value="0" min="0" max="59" placeholder="Sec">
                    </div>

                    <div class="timer-display" id="timerDisplay">00:00:00</div>

                    <div class="timer-controls">
                        <button class="timer-btn start" id="btnStart" onclick="startTimer()">▶</button>
                        <button class="timer-btn lap" id="btnLap" onclick="lapTimer()" style="display: none;">⏎</button>
                        <button class="timer-btn stop" id="btnStop" onclick="resetTimer()">■</button>
                    </div>

                    <div class="laps-list" id="lapsList"></div>
                </div>
            </div>
        </div>

        <!-- Body Stats Page -->
        <div class="page" id="page-body">
            <div class="card" style="margin-bottom: 24px;">
                <div class="card-title">📏 Log Body Measurements</div>
                <form class="body-stats-form" id="bodyStatsForm" onsubmit="saveBodyStats(event)">
                    <div class="form-group">
                        <label>Date</label>
                        <input type="date" id="bodyDate" required>
                    </div>
                    <div class="form-group">
                        <label>Weight (lbs)</label>
                        <input type="number" id="bodyWeight" step="0.1" placeholder="e.g., 165">
                    </div>
                    <div class="form-group">
                        <label>Body Fat %</label>
                        <input type="number" id="bodyFat" step="0.1" placeholder="e.g., 18">
                    </div>
                    <div class="form-group">
                        <label>Chest (in)</label>
                        <input type="number" id="bodyChest" step="0.1" placeholder="e.g., 40">
                    </div>
                    <div class="form-group">
                        <label>Waist (in)</label>
                        <input type="number" id="bodyWaist" step="0.1" placeholder="e.g., 32">
                    </div>
                    <div class="form-group">
                        <label>Arms (in)</label>
                        <input type="number" id="bodyArms" step="0.1" placeholder="e.g., 14">
                    </div>
                    <div class="form-group" style="display: flex; align-items: flex-end;">
                        <button type="submit" class="btn btn-primary" style="width: 100%;">💾 Save</button>
                    </div>
                </form>
            </div>

            <div class="card">
                <div class="card-title">📈 Measurement History</div>
                <div class="body-stats-history">
                    <table class="stats-table" id="bodyStatsTable">
                        <thead>
                            <tr>
                                <th>Date</th>
                                <th>Weight</th>
                                <th>Body Fat</th>
                                <th>Chest</th>
                                <th>Waist</th>
                                <th>Arms</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody id="bodyStatsBody"></tbody>
                    </table>
                </div>
            </div>

            <div class="danger-zone">
                <p style="color: var(--danger); font-weight: 600; margin-bottom: 12px;">⚠️ Danger Zone</p>
                <button class="btn btn-danger" onclick="clearAllData()">🗑️ Clear All Data</button>
            </div>
        </div>
    </main>

    <!-- Toast -->
    <div class="toast" id="toast"></div>

    <script>
        // ============ Data Management ============
        function getData(key) {
            try {
                return JSON.parse(localStorage.getItem(key)) || [];
            } catch {
                return [];
            }
        }

        function setData(key, data) {
            localStorage.setItem(key, JSON.stringify(data));
        }

        // ============ Navigation ============
        document.querySelectorAll('.nav-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
                document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
                btn.classList.add('active');
                document.getElementById(`page-${btn.dataset.page}`).classList.add('active');
                if (btn.dataset.page === 'dashboard') refreshDashboard();
                if (btn.dataset.page === 'history') renderHistory();
                if (btn.dataset.page === 'body') renderBodyStats();
            });
        });

        // ============ Date Setup ============
        const today = new Date();
        document.getElementById('currentDate').textContent = today.toLocaleDateString('en-US', {
            weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
        });
        document.getElementById('workoutDate').value = today.toISOString().split('T')[0];
        document.getElementById('bodyDate').value = today.toISOString().split('T')[0];

        // ============ Workout Templates ============
        const templates = {
            push: {
                type: 'strength',
                exercises: [
                    { name: 'Bench Press', sets: 4, reps: 8, weight: 135 },
                    { name: 'Overhead Press', sets: 3, reps: 10, weight: 95 },
                    { name: 'Incline Dumbbell Press', sets: 3, reps: 12, weight: 50 },
                    { name: 'Lateral Raises', sets: 3, reps: 15, weight: 20 },
                    { name: 'Tricep Pushdowns', sets: 3, reps: 12, weight: 40 },
                ]
            },
            pull: {
                type: 'strength',
                exercises: [
                    { name: 'Deadlift', sets: 4, reps: 5, weight: 225 },
                    { name: 'Pull-Ups', sets: 4, reps: 8, weight: 0 },
                    { name: 'Barbell Rows', sets: 3, reps: 10, weight: 135 },
                    { name: 'Face Pulls', sets: 3, reps: 15, weight: 30 },
                    { name: 'Bicep Curls', sets: 3, reps: 12, weight: 30 },
                ]
            },
            legs: {
                type: 'strength',
                exercises: [
                    { name: 'Squats', sets: 4, reps: 8, weight: 185 },
                    { name: 'Romanian Deadlift', sets: 3, reps: 10, weight: 155 },
                    { name: 'Leg Press', sets: 3, reps: 12, weight: 270 },
                    { name: 'Walking Lunges', sets: 3, reps: 12, weight: 40 },
                    { name: 'Calf Raises', sets: 4, reps: 15, weight: 90 },
                ]
            },
            cardio: {
                type: 'cardio',
                exercises: [
                    { name: 'Treadmill Run', sets: 1, reps: 30, weight: 0 },
                    { name: 'Jump Rope', sets: 3, reps: 5, weight: 0 },
                    { name: 'Rowing Machine', sets: 1, reps: 15, weight: 0 },
                ]
            },
            fullbody: {
                type: 'strength',
                exercises: [
                    { name: 'Squats', sets: 3, reps: 10, weight: 155 },
                    { name: 'Bench Press', sets: 3, reps: 10, weight: 115 },
                    { name: 'Barbell Rows', sets: 3, reps: 10, weight: 115 },
                    { name: 'Overhead Press', sets: 3, reps: 10, weight: 75 },
                    { name: 'Romanian Deadlift', sets: 3, reps: 10, weight: 135 },
                    { name: 'Plank', sets: 3, reps: 60, weight: 0 },
                ]
            },
            yoga: {
                type: 'flexibility',
                exercises: [
                    { name: 'Sun Salutations', sets: 5, reps: 1, weight: 0 },
                    { name: 'Warrior Sequence', sets: 2, reps: 1, weight: 0 },
                    { name: 'Balance Poses', sets: 3, reps: 1, weight: 0 },
                    { name: 'Hip Openers', sets: 2, reps: 1, weight: 0 },
                    { name: 'Savasana', sets: 1, reps: 1, weight: 0 },
                ]
            }
        };

        function loadTemplate(name) {
            const template = templates[name];
            document.getElementById('workoutType').value = template.type;
            document.getElementById('exerciseList').innerHTML = '';

            template.exercises.forEach(ex => {
                addExercise(ex.name, ex.sets, ex.reps, ex.weight);
            });

            showToast('✅ Template loaded!', 'success');
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        // ============ Exercise Management ============
        let exerciseCount = 0;

        function addExercise(name = '', sets = '', reps = '', weight = '') {
            exerciseCount++;
            const id = exerciseCount;
            const div = document.createElement('div');
            div.className = 'exercise-entry';
            div.id = `exercise-${id}`;
            div.innerHTML = `
                <div class="form-group">
                    <label>Exercise</label>
                    <input type="text" placeholder="e.g., Bench Press" value="${name}" class="ex-name" required>
                </div>
                <div class="form-group">
                    <label>Sets</label>
                    <input type="number" placeholder="3" value="${sets}" class="ex-sets" min="1">
                </div>
                <div class="form-group">
                    <label>Reps</label>
                    <input type="number" placeholder="10" value="${reps}" class="ex-reps" min="1">
                </div>
                <div class="form-group">
                    <label>Weight (lbs)</label>
                    <input type="number" placeholder="0" value="${weight}" class="ex-weight" min="0">
                </div>
                <button type="button" class="remove-exercise" onclick="removeExercise(${id})">✕</button>
            `;
            document.getElementById('exerciseList').appendChild(div);
        }

        function removeExercise(id) {
            const el = document.getElementById(`exercise-${id}`);
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateX(20px)';
                setTimeout(() => el.remove(), 200);
            }
        }

        // ============ Save Workout ============
        document.getElementById('workoutForm').addEventListener('submit', (e) => {
            e.preventDefault();

            const exercises = [];
            document.querySelectorAll('.exercise-entry').forEach(entry => {
                const name = entry.querySelector('.ex-name').value;
                if (name) {
                    exercises.push({
                        name,
                        sets: parseInt(entry.querySelector('.ex-sets').value) || 0,
                        reps: parseInt(entry.querySelector('.ex-reps').value) || 0,
                        weight: parseFloat(entry.querySelector('.ex-weight').value) || 0,
                    });
                }
            });

            const workout = {
                id: Date.now(),
                type: document.getElementById('workoutType').value,
                date: document.getElementById('workoutDate').value,
                duration: parseInt(document.getElementById('workoutDuration').value) || 0,
                calories: parseInt(document.getElementById('workoutCalories').value) || 0,
                notes: document.getElementById('workoutNotes').value,
                exercises,
                timestamp: new Date().toISOString()
            };

            const workouts = getData('workouts');
            workouts.unshift(workout);
            setData('workouts', workouts);

            // Reset form
            document.getElementById('workoutForm').reset();
            document.getElementById('workoutDate').value = today.toISOString().split('T')[0];
            document.getElementById('exerciseList').innerHTML = '';
            exerciseCount = 0;

            showToast('🎉 Workout saved successfully!', 'success');
        });

        // ============ History ============
        function renderHistory() {
            const workouts = getData('workouts');
            const filter = document.getElementById('historyFilter').value;
            const filtered = filter === 'all' ? workouts : workouts.filter(w => w.type === filter);
            const container = document.getElementById('historyContainer');

            if (filtered.length === 0) {
                container.innerHTML = `
                    <div class="empty-state">
                        <div class="empty-state-icon">📋</div>
                        <div class="empty-state-text">No workouts found</div>
                        <p>Start logging workouts to see your history!</p>
                    </div>
                `;
                return;
            }

            const typeIcons = { strength: '🏋️', cardio: '🏃', flexibility: '🧘', sports: '⚽' };
            const typeNames = { strength: 'Strength Training', cardio: 'Cardio', flexibility: 'Flexibility', sports: 'Sports' };

            container.innerHTML = filtered.map(w => `
                <div class="workout-card type-${w.type}">
                    <div class="workout-header">
                        <div class="workout-type">
                            <div class="workout-type-icon">${typeIcons[w.type] || '🏋️'}</div>
                            <div>
                                <div class="workout-type-name">${typeNames[w.type] || w.type}</div>
                                <div class="workout-type-date">${new Date(w.date + 'T12:00:00').toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })}</div>
                            </div>
                        </div>
                        <div class="workout-meta">
                            <div class="workout-meta-item">
                                <div class="workout-meta-value">${w.duration}<span style="font-size:13px;font-weight:400;color:var(--text-muted)">min</span></div>
                            </div>
                            ${w.calories ? `<div class="workout-meta-item">
                                <div class="workout-meta-value">${w.calories}<span style="font-size:13px;font-weight:400;color:var(--text-muted)">cal</span></div>
                            </div>` : ''}
                            <div>
                                <button class="btn btn-danger" onclick="deleteWorkout(${w.id})">🗑️</button>
                            </div>
                        </div>
                    </div>
                    ${w.exercises && w.exercises.length > 0 ? `
                        <div class="workout-exercises">
                            ${w.exercises.map(ex => `
                                <div class="exercise-row">
                                    <span class="exercise-name">${ex.name}</span>
                                    <span class="exercise-details">${ex.sets ? ex.sets + ' × ' + ex.reps : ''}${ex.weight ? ' @ ' + ex.weight + ' lbs' : ''}</span>
                                </div>
                            `).join('')}
                        </div>
                    ` : ''}
                    ${w.notes ? `<p style="margin-top:12px;font-size:14px;color:var(--text-muted);font-style:italic;">"${w.notes}"</p>` : ''}
                </div>
            `).join('');
        }

        function deleteWorkout(id) {
            if (!confirm('Delete this workout?')) return;
            let workouts = getData('workouts');
            workouts = workouts.filter(w => w.id !== id);
            setData('workouts', workouts);
            renderHistory();
            refreshDashboard();
            showToast('🗑️ Workout deleted', 'error');
        }

        // ============ Timer ============
        let timerInterval = null;
        let timerSeconds = 0;
        let timerRunning = false;
        let timerMode = 'stopwatch';
        let laps = [];

        function switchTimerMode(mode) {
            timerMode = mode;
            document.querySelectorAll('.timer-mode-btn').forEach(b => {
                b.classList.toggle('active', b.dataset.mode === mode);
            });
            document.getElementById('countdownSettings').style.display = mode === 'countdown' ? 'flex' : 'none';
            resetTimer();
        }

        function startTimer() {
            const btn = document.getElementById('btnStart');

            if (timerRunning) {
                // Pause
                clearInterval(timerInterval);
                timerRunning = false;
                btn.textContent = '▶';
                btn.className = 'timer-btn start';
                return;
            }

            // Start
            if (timerMode === 'countdown' && timerSeconds === 0) {
                const min = parseInt(document.getElementById('countdownMin').value) || 0;
                const sec = parseInt(document.getElementById('countdownSec').value) || 0;
                timerSeconds = min * 60 + sec;
                if (timerSeconds === 0) return;
            }

            timerRunning = true;
            btn.textContent = '⏸';
            btn.className = 'timer-btn pause';
            document.getElementById('btnLap').style.display = timerMode === 'stopwatch' ? 'inline-flex' : 'none';

            timerInterval = setInterval(() => {
                if (timerMode === 'stopwatch') {
                    timerSeconds++;
                } else {
                    timerSeconds--;
                    if (timerSeconds <= 0) {
                        timerSeconds = 0;
                        clearInterval(timerInterval);
                        timerRunning = false;
                        btn.textContent = '▶';
                        btn.className = 'timer-btn start';
                        showToast('⏰ Timer complete!', 'success');
                        // Try to play a beep
                        try {
                            const ctx = new (window.AudioContext || window.webkitAudioContext)();
                            const osc = ctx.createOscillator();
                            osc.connect(ctx.destination);
                            osc.frequency.value = 800;
                            osc.start();
                            setTimeout(() => osc.stop(), 300);
                        } catch(e) {}
                    }
                }
                updateTimerDisplay();
            }, 1000);
        }

        function lapTimer() {
            if (!timerRunning) return;
            const lastLap = laps.length > 0 ? laps[laps.length - 1].total : 0;
            laps.push({ total: timerSeconds, split: timerSeconds - lastLap });
            renderLaps();
        }

        function resetTimer() {
            clearInterval(timerInterval);
            timerRunning = false;
            timerSeconds = 0;
            laps = [];
            document.getElementById('btnStart').textContent = '▶';
            document.getElementById('btnStart').className = 'timer-btn start';
            document.getElementById('btnLap').style.display = 'none';
            updateTimerDisplay();
            renderLaps();
        }

        function updateTimerDisplay() {
            const h = Math.floor(timerSeconds / 3600);
            const m = Math.floor((timerSeconds % 3600) / 60);
            const s = timerSeconds % 60;
            document.getElementById('timerDisplay').textContent =
                `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
        }

        function renderLaps() {
            const container = document.getElementById('lapsList');
            if (laps.length === 0) {
                container.innerHTML = '';
                return;
            }
            container.innerHTML = laps.map((lap, i) => `
                <div class="lap-item">
                    <span class="lap-number">Lap ${i + 1}</span>
                    <span class="lap-time">${formatTime(lap.total)}</span>
                    <span class="lap-split">+${formatTime(lap.split)}</span>
                </div>
            `).reverse().join('');
        }

        function formatTime(secs) {
            const m = Math.floor(secs / 60);
            const s = secs % 60;
            return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
        }

        // ============ Body Stats ============
        function saveBodyStats(e) {
            e.preventDefault();
            const stat = {
                id: Date.now(),
                date: document.getElementById('bodyDate').value,
                weight: parseFloat(document.getElementById('bodyWeight').value) || null,
                bodyFat: parseFloat(document.getElementById('bodyFat').value) || null,
                chest: parseFloat(document.getElementById('bodyChest').value) || null,
                waist: parseFloat(document.getElementById('bodyWaist').value) || null,
                arms: parseFloat(document.getElementById('bodyArms').value) || null,
            };

            const stats = getData('bodyStats');
            stats.unshift(stat);
            stats.sort((a, b) => new Date(b.date) - new Date(a.date));
            setData('bodyStats', stats);

            document.getElementById('bodyStatsForm').reset();
            document.getElementById('bodyDate').value = today.toISOString().split('T')[0];

            renderBodyStats();
            showToast('📏 Body stats saved!', 'success');
        }

        function renderBodyStats() {
            const stats = getData('bodyStats');
            const tbody = document.getElementById('bodyStatsBody');

            if (stats.length === 0) {
                tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:40px;color:var(--text-muted);">No measurements logged yet</td></tr>`;
                return;
            }

            tbody.innerHTML = stats.map((s, i) => {
                const prev = stats[i + 1];
                const weightTrend = prev && s.weight && prev.weight
                    ? (s.weight > prev.weight ? '↑' : s.weight < prev.weight ? '↓' : '→')
                    : '';
                const weightClass = weightTrend === '↑' ? 'trend-up' : weightTrend === '↓' ? 'trend-down' : 'trend-same';

                return `
                    <tr>
                        <td>${new Date(s.date + 'T12:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</td>
                        <td>${s.weight ? `${s.weight} lbs <span class="${weightClass}">${weightTrend}</span>` : '—'}</td>
                        <td>${s.bodyFat ? s.bodyFat + '%' : '—'}</td>
                        <td>${s.chest ? s.chest + '"' : '—'}</td>
                        <td>${s.waist ? s.waist + '"' : '—'}</td>
                        <td>${s.arms ? s.arms + '"' : '—'}</td>
                        <td><button class="btn btn-danger" onclick="deleteBodyStat(${s.id})" style="padding:6px 10px;">✕</button></td>
                    </tr>
                `;
            }).join('');
        }

        function deleteBodyStat(id) {
            let stats = getData('bodyStats');
            stats = stats.filter(s => s.id !== id);
            setData('bodyStats', stats);
            renderBodyStats();
        }

        // ============ Dashboard ============
        function refreshDashboard() {
            const workouts = getData('workouts');
            const now = new Date();
            const weekStart = new Date(now);
            weekStart.setDate(now.getDate() - now.getDay());
            weekStart.setHours(0, 0, 0, 0);

            const weekWorkouts = workouts.filter(w => new Date(w.date + 'T12:00:00') >= weekStart);

            // Stats
            document.getElementById('totalWorkouts').textContent = workouts.length;
            document.getElementById('totalCalories').textContent = weekWorkouts.reduce((sum, w) => sum + (w.calories || 0), 0).toLocaleString();
            document.getElementById('totalMinutes').textContent = weekWorkouts.reduce((sum, w) => sum + (w.duration || 0), 0);
            document.getElementById('weekWorkouts').textContent = weekWorkouts.length;

            // Goals
            const wk = weekWorkouts.length;
            const cal = weekWorkouts.reduce((s, w) => s + (w.calories || 0), 0);
            const min = weekWorkouts.reduce((s, w) => s + (w.duration || 0), 0);

            document.getElementById('goalWorkoutText').textContent = `${wk}/5`;
            document.getElementById('goalWorkoutBar').style.width = `${Math.min(100, (wk / 5) * 100)}%`;

            document.getElementById('goalCalorieText').textContent = `${cal.toLocaleString()}/2,000`;
            document.getElementById('goalCalorieBar').style.width = `${Math.min(100, (cal / 2000) * 100)}%`;

            document.getElementById('goalMinuteText').textContent = `${min}/150`;
            document.getElementById('goalMinuteBar').style.width = `${Math.min(100, (min / 150) * 100)}%`;

            // Weekly chart
            const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
            const dayData = new Array(7).fill(0);

            weekWorkouts.forEach(w => {
                const d = new Date(w.date + 'T12:00:00').getDay();
                dayData[d] += w.duration || 0;
            });

            const maxVal = Math.max(...dayData, 1);
            const chartContainer = document.getElementById('weeklyChart');
            chartContainer.innerHTML = days.map((day, i) => `
                <div class="bar-wrapper">
                    <div class="bar-value">${dayData[i]}m</div>
                    <div class="bar" style="height: ${(dayData[i] / maxVal) * 100}%${i === now.getDay() ? '; background: linear-gradient(180deg, var(--secondary), #55efc4);' : ''}"></div>
                    <div class="bar-label" style="${i === now.getDay() ? 'color: var(--secondary);' : ''}">${day}</div>
                </div>
            `).join('');

            // Streak
            const streakCount = calculateStreak(workouts);
            document.getElementById('streakCount').textContent = streakCount;

            // Recent Activity
            const recent = workouts.slice(0, 5);
            const activityContainer = document.getElementById('recentActivity');
            const typeIcons = { strength: '🏋️', cardio: '🏃', flexibility: '🧘', sports: '⚽' };
            const colors = { strength: 'var(--primary)', cardio: 'var(--accent)', flexibility: 'var(--secondary)', sports: 'var(--danger)' };

            if (recent.length === 0) {
                activityContainer.innerHTML = `
                    <div class="empty-state">
                        <div class="empty-state-icon">🏃</div>
                        <div class="empty-state-text">No activities yet</div>
                        <p>Log your first workout to get started!</p>
                    </div>
                `;
            } else {
                activityContainer.innerHTML = recent.map(w => `
                    <div class="activity-item">
                        <div class="activity-dot" style="background: ${colors[w.type] || 'var(--primary)'}"></div>
                        <div class="activity-text">
                            ${typeIcons[w.type] || '🏋️'} <strong>${w.type.charAt(0).toUpperCase() + w.type.slice(1)}</strong>
                            — ${w.duration}min${w.calories ? ', ' + w.calories + ' cal' : ''}
                            ${w.exercises && w.exercises.length > 0 ? ` (${w.exercises.length} exercises)` : ''}
                        </div>
                        <div class="activity-time">${formatRelativeDate(w.date)}</div>
                    </div>
                `).join('');
            }
        }

        function calculateStreak(workouts) {
            if (workouts.length === 0) return 0;
            const dates = [...new Set(workouts.map(w => w.date))].sort().reverse();
            let streak = 0;
            const today = new Date();
            today.setHours(0, 0, 0, 0);

            for (let i = 0; i < 365; i++) {
                const checkDate = new Date(today);
                checkDate.setDate(today.getDate() - i);
                const dateStr = checkDate.toISOString().split('T')[0];
                if (dates.includes(dateStr)) {
                    streak++;
                } else if (i === 0) {
                    continue; // Today doesn't break streak
                } else {
                    break;
                }
            }
            return streak;
        }

        function formatRelativeDate(dateStr) {
            const date = new Date(dateStr + 'T12:00:00');
            const now = new Date();
            const diff = Math.floor((now - date) / (1000 * 60 * 60 * 24));
            if (diff === 0) return 'Today';
            if (diff === 1) return 'Yesterday';
            if (diff < 7) return `${diff} days ago`;
            return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        }

        // ============ Clear All Data ============
        function clearAllData() {
            if (!confirm('Are you sure you want to delete ALL data? This cannot be undone.')) return;
            if (!confirm('Really? This will delete all workouts and body stats permanently.')) return;
            localStorage.removeItem('workouts');
            localStorage.removeItem('bodyStats');
            refreshDashboard();
            renderHistory();
            renderBodyStats();
            showToast('🗑️ All data cleared', 'error');
        }

        // ============ Toast ============
        function showToast(message, type = 'success') {
            const toast = document.getElementById('toast');
            toast.textContent = message;
            toast.className = `toast ${type} show`;
            setTimeout(() => toast.classList.remove('show'), 3000);
        }

        // ============ Init ============
        refreshDashboard();
        addExercise(); // Start with one exercise row
    </script>
</body>
</html>
